function CompetePKResultDialog:JudgeExecuteAnimator()
    local people = self.comp:GetPeople()
    local prefab = tostring(self.comp:GetPrefabId())
    local userPkPointInfo = self.comp:GetUserPkPointInfo()
    local onePoint = checkInt(userPkPointInfo[tostring(people[1])])
    local twoPoint = checkInt(userPkPointInfo[tostring(people[2])])
    local endName = "02"
    local frontName = "Leading"
    --- 活动结束前 播放的是 领先的动画， 活动结束后 ， 播放胜利的动画
    if onePoint > twoPoint then
        endName = "01"
    end
    if self.comp:IsActivityEnd() then
        frontName = "WIN"
    end
    local animatorTable = Animators[prefab]
    local key = string.format("%s_%s" , frontName , endName)
    local animName = animatorTable[key]
    self:PlayAnim(self.animator , animName)
end

function CompetePKResultDialog:RecordsPlayAnimation()
    if self.comp:IsActivityEnd() then
        -- 结束记录
        self.comp:SetEndDayEnter()
    else
        -- 今日比拼记录
        self.comp:SetCurentDayEnter()
    end
end

---@param anim UnityEngine.Animator
---@param animName integer
function CompetePKResultDialog:PlayAnim(anim , animName)
    animName = Animator.StringToHash(animName)
    cs_coroutine.yield_return(anim:PlayAndWait(animName))
    KTool.SetActive(self.ClickClose , true)
end

